</section></main><script>const editButton=document.getElementById('editProfileButton'), form=document.getElementById('profileEditForm'), details=document.getElementById('profileDetails');function editMode(on){form.classList.toggle('hidden',!on);details.classList.toggle('hidden',on);editButton.classList.toggle('hidden',on)}editButton?.addEventListener('click',()=>editMode(true));document.getElementById('cancelEditButton')?.addEventListener('click',()=>editMode(false));document.getElementById('profilePhotoInput')?.addEventListener('change',e=>{const f=e.target.files?.[0], img=document.getElementById('profilePhotoPreview');if(f){img.src=URL.createObjectURL(f);img.classList.remove('hidden')}});document.getElementById('shareProfileButton')?.addEventListener('click',async()=>{const url='{{ route('profile.public', auth()->id()) }}';try{if(navigator.share)await navigator.share({title:'My AutoBugTriage profile',url});else{await navigator.clipboard.writeText(url);document.getElementById('shareFeedback').textContent='Profile link copied'}}catch(e){if(e.name!=='AbortError')document.getElementById('shareFeedback').textContent='Could not share. Profile link: '+url}});@if($errors->any())editMode(true);@endif</script></body></html>
